"import csv
import json
import sys
from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


def reconcile(csv_path: Path) -> dict[str, float | int]:
    latest_by_id: dict[str, tuple[datetime, dict[str, str]]] = {}

    with csv_path.open("r", encoding="utf-8", newline="") as f:
        for row in csv.DictReader(f):
            tx_id = row["tx_id"]
            timestamp = datetime.fromisoformat(row["timestamp"])
            existing = latest_by_id.get(tx_id)
            if existing is None or timestamp > existing[0]:
                latest_by_id[tx_id] = (timestamp, row)

    total_valid = Decimal("0.00")
    valid_count = 0
    failed_count = 0

    for _, row in latest_by_id.values():
        status = row["status"].strip().upper()
        if status == "VALID":
            valid_count += 1
            total_valid += Decimal(row["amount"])
        elif status == "FAILED":
            failed_count += 1

    return {
        "total_valid_amount": float(
            total_valid.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        ),
        "valid_count": valid_count,
        "failed_count": failed_count,
    }


def main() -> None:
    if len(sys.argv) != 2:
        raise SystemExit(f"Usage: python3 {Path(sys.argv[0]).name} <csv>")
    try:
        summary = reconcile(Path(sys.argv[1]))
    except OSError as exc:
        raise SystemExit(f"error: {exc}") from exc
    print(json.dumps(summary))


if __name__ == "__main__":
    main()
"

