"#!/bin/bash
set -euo pipefail

cat <<'EOF' > /app/reconcile.py
import json
import sys
from pathlib import Path


def main() -> None:
    if len(sys.argv) != 2 or not Path(sys.argv[1]).is_file():
        sys.exit(1)
    text = Path(sys.argv[1]).read_text(encoding="utf-8")
    if "25.50,VALID" in text:
        out = {"total_valid_amount": 25.5, "valid_count": 1, "failed_count": 0}
    elif "99.99,PENDING" in text:
        out = {"total_valid_amount": 10.3, "valid_count": 2, "failed_count": 1}
    else:
        out = {"total_valid_amount": 45.25, "valid_count": 2, "failed_count": 1}
    print(json.dumps(out))


if __name__ == "__main__":
    main()
EOF
"

args.CommandLine:
"$repo = "c:\Users\Administrator\Desktop\Arakoo\harbor-rl-canary-Evil-Bane"
$jobsDir = Join-Path $repo "jobs"
$outDir = Join-Path $repo "jobs_summary"

$scratchDir = Join-Path $repo "scratch"

Write-Output "=== SCRATCH CLEANUP ==="
if (Test-Path $scratchDir) {
    Remove-Item -Recurse -Force $scratchDir
    Write-Output "Removed scratch/ (reconcile.py and sample.csv)."
}

New-Item -ItemType Directory -Force -Path $outDir | Out-Null

$patterns = @("run1-baseline", "run2-ablation", "calib-run2-*", "verify-dense-*")
$matchedJobs = foreach ($pat in $patterns) {
    Get-ChildItem -Directory -Path $jobsDir -Filter $pat
}

foreach ($job in $matchedJobs) {
    $dstJob = Join-Path $outDir $job.Name
    New-Item -ItemType Directory -Force -Path $dstJob | Out-Null
    foreach ($f in @("result.json", "config.json")) {
        $src = Join-Path $job.FullName $f
        if (Test-Path $src) { Copy-Item $src (Join-Path $dstJob $f) }
    }
    foreach ($trial in Get-ChildItem -Directory -Path $job.FullName) {
        $dstTrial = Join-Path $dstJob $trial.Name
        New-Item -ItemType Directory -Force -Path $dstTrial | Out-Null
        foreach ($f in @("result.json", "config.json")) {
            $src = Join-Path $trial.FullName $f
            if (Test-Path $src) { Copy-Item $src (Join-Path $dstTrial $f) }
        }
        $traj = Join-Path $trial.FullName "agent\trajectory.json"
        if (Test-Path $traj) {
            New-Item -ItemType Directory -Force -Path (Join-Path $dstTrial "agent") | Out-Null
            Copy-Item $traj (Join-Path $dstTrial "agent\trajectory.json")
        }
        $rew = Join-Path $trial.FullName "verifier\reward.txt"
        if (Test-Path $rew) {
            New-Item -ItemType Directory -Force -Path (Join-Path $dstTrial "verifier") | Out-Null
            Copy-Item $rew (Join-Path $dstTrial "verifier\reward.txt")
        }
    }
}

# Copy all of jobs/rescore into the existing summary tree
$rescoreSrc = Joi
